#if DEBUG
import Foundation

// Local display-only extracts from user-provided Android-target screenshots.
// Rectangles and provenance are recorded in Docs/VisualParity/R01_ACCEPTANCE.md.
enum DebugR01ImageSamples {
    static func data(for key: String) -> Data? {
        let encoded: String
        switch key {
        case "user": encoded = DebugR01SampleUser.encoded
        case "forum": encoded = DebugR01SampleForum.encoded
        case "media1": encoded = DebugR01SampleMedia1.encoded
        case "media2": encoded = DebugR01SampleMedia2.encoded
        case "media3": encoded = DebugR01SampleMedia3.encoded
        default: return nil
        }
        return Data(base64Encoded: encoded, options: .ignoreUnknownCharacters)
    }
}

